    guide_overview_boards_desc: "MASTER → SCHEDULING → READY TO SCHEDULED → BLANKS → SCREENS → NECK → EJEMPLOS → COMPLETOS → FINAL BILL. Las máquinas (MAQUINA1-14) son tableros de producción activa.",
