    guide_overview_title: "System Overview",
    guide_overview_mos_desc: "Production CRM for managing textile manufacturing orders. Each order moves through multiple boards according to its production status.",
    guide_overview_boards_label: "Main boards",
    guide_overview_boards_desc: "MASTER → SCHEDULING → READY TO SCHEDULED → BLANKS → SCREENS → NECK → EJEMPLOS → COMPLETOS → FINAL BILL. The machines (MAQUINA1-14) are active production boards.",
    guide_overview_master_label: "MASTER view",
    guide_overview_master_desc: "Shows ALL active orders across every board (except PAPELERA DE RECICLAJE). Use it for global search or general oversight.",
    guide_overview_secret_label: "Secret code",
    guide_overview_secret_desc: "Type '201492' in the search box to open this guide at any time.",
    guide_search_title: "Global Search",
    guide_search_how_label: "How to search",
    guide_search_how_desc: "Type in the header search box and press Enter. Searches by: order number, PO, client, branding or notes.",
    guide_search_exact_label: "Exact match",
    guide_search_exact_desc: "If exactly 1 order is found, it navigates automatically to its board and shows a toast with its location.",
    guide_search_multi_label: "Multiple results",
    guide_search_multi_desc: "If there are multiple matches, they are shown in a results list so you can pick one.",
    guide_search_code_desc: "Special code that opens this system guide.",
    guide_auto_title: "Automation Engine",
    guide_auto_what_label: "What are they?",
    guide_auto_what_desc: "Rules that run automatically when an event happens on an order. No manual intervention.",
    guide_auto_flow_label: "Execution flow",
    guide_auto_flow_desc: "EVENT (trigger) → CONDITIONS (are they met?) → ACTION. If the conditions are not met, the automation is skipped silently.",
    guide_auto_triggers_label: "Available triggers",
    guide_auto_triggers_desc: "create (order created), move (order moved between boards), update (field updated), status_change (specific status change).",
    guide_auto_conditions_label: "Conditions",
    guide_auto_conditions_desc: "Evaluated against the order's fields. Use watch_field + watch_value to detect specific changes, or from_board/to_board for moves.",
    guide_auto_actions_label: "Available actions",
    guide_auto_actions_desc: "send_email (via Resend), move_board (move the order to another board), assign_field (set a field value), notify_slack (webhook).",
    guide_auto_scoped_label: "Scoped boards",
    guide_auto_scoped_desc: "Each automation can be limited to specific boards. If the 'boards' field is empty, it applies to ALL boards.",
